#### 3.3. Provide a Minimal Authentication Layer

Below is a simple JWT‑based guard for demonstration. In a real use‑case you’d use a database, OAuth, or LDAP.

```js
const jwt = require('jsonwebtoken');

const AUTH_SECRET = process.env.AUTH_SECRET || 'somesecret'; // set in env

function authMiddleware(req, res, next) {
  const header = req.headers['authorization'];
  if (!header) return res.status(401).json({ error: 'Missing token' });

  const token = header.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Malformed token' });

  jwt.verify(token, AUTH_SECRET, (err, payload) => {
    if (err) return res.status(401).json({ error: 'Invalid token' });
    req.user = payload;          // attach decoded payload
    next();
  });
}

// Protect the /users endpoint
app.get('/users', authMiddleware, (req, res) => {
  // You might filter results based on req.user.role here
  res.json([...]); // same body
});
```

*Why?* Forces clients to prove identity before accessing potentially sensitive data.

