app.get('/profile/:id', [
  param('id').isInt({ min: 1 })
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  // safe to use req.params.id
});
```

#### 3.5. Use Database Libraries Safely

If you move `/users` to a database, use parameterized queries:

```js
// Using a generic async function example with an ORM
app.get('/users', authMiddleware, async (req, res) => {
  try {
    const users = await db.query('SELECT id, name, email FROM users');
    res.json(users);
  } catch (err) {
    res.status(500).json({ error: 'Server error' });
  }
});
```

If you persist a filter:

```js
const search = req.query.search;
const result = await db.query(
  'SELECT id, name, email FROM users WHERE name ILIKE $1',
  [`%${search}%`]
);
```

Always use the driver's “binding” interface, never string concatenation.

