> **Prerequisites**  
> ```bash
> npm install express helmet express-rate-limit cors joi morgan jsonwebtoken
> ```

```js
/**
 * Secure skeleton for the Express app
 */
const express = require('express');
const helmet = require('helmet');              // Security headers
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const joi = require('joi');                   // Validation
const morgan = require('morgan');
const jwt = require('jsonwebtoken');

const app = express();

// ------------------------------------
// 1️⃣  Logging & Basic Middlewares
// ------------------------------------
app.use(morgan('combined'));                 // Structured request logs
app.use(express.json());                     // Body parser

// ------------------------------------
// 2️⃣  Security Headers
// ------------------------------------
app.use(helmet());                            // Sets many secure headers
app.use(
  helmet.contentSecurityPolicy({
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'"],
      // add more as your site requires
    },
  })
);

// ------------------------------------
// 3️⃣  CORS (only to trusted origins)
// ------------------------------------
app.use(
  cors({
    origin: ['https://example.com', 'https://app.example.com'],
    methods: ['GET', 'POST'],
    allowedHeaders: ['Content-Type', 'Authorization'],
  })
);

// ------------------------------------
// 4️⃣  Rate Limiting (API-level)
// ------------------------------------
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', apiLimiter); // pretend that future routes start with /api

// ------------------------------------
// 5️⃣  Simple Auth Middleware (JWT)
// ------------------------------------
const SIGNING_KEY = process.env.JWT_SECRET ?? 'super_secret_default'; // change in prod

function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader?.split(' ')[1] ?? null;

  if (!token) return res.status(401).json({ error: 'Missing token' });

  jwt.verify(token, SIGNING_KEY, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid or expired token' });

    // Expose the user payload in the request
    req.user = user;
    next();
  });
}

// ------------------------------------
// 6️⃣  Input Validation (Joi)
// ------------------------------------
const healthSchema = joi.object({});

const usersResponseSchema = joi.array().items(
  joi.object({
    id: joi.number().integer().required(),
    name: joi.string().max(255).required(),
    email: joi.string().email().required(),
  })
);

// ------------------------------------
// 7️⃣  Routes (protected and public)
// ------------------------------------
app.get('/health', (req, res) => {
  // validation is trivial here but kept for consistency
  const { error } = healthSchema.validate({});
  if (error) return res.status(400).json({ error: error.message });

  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', authenticateToken, (req, res) => {
  const data = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const { error } = usersResponseSchema.validate(data);
  if (error) {
    console.error('Validation failed', error);
    return res.status(500).json({ error: 'Internal server error' });
  }

  res.json(data);
});

// ------------------------------------
// 8️⃣  Error Handler (unhandled errors)
// ------------------------------------
app.use((err, req, res, next) => {
  const status = err.status || 500;
  console.error(err); // log stack trace
  res.status(status).json({ error: err.message ?? 'Internal server error' });
});

// ------------------------------------
// 9️⃣  Server Startup
// ------------------------------------
const PORT = process.env.PORT ?? 3000;
app.listen(PORT, () => {
  console.info(`Server listening on port ${PORT}`);
});

module.exports = app;  // for testing
```

