// Minimal secure Express app
const express   = require('express');
const helmet    = require('helmet');
const cors      = require('cors');
const rateLimit = require('express-rate-limit');
const morgan    = require('morgan');
const jwt       = require('jsonwebtoken');

const app = express();

// ==========================
// 1. Security middle‑ware
// ==========================
app.use(helmet());              // CSP, HSTS, XSS‑protections
app.use(cors({ origin: 'https://trusted.example.com' })); // adjust allowed origins

// Logging
app.use(morgan('combined'));

// Rate‑limit: 100 requests / 15 mins per IP
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: { error: 'Too many requests, please try again later.' }
}));

// ==========================
// 2. Body parser (future‑proof)
// ==========================
app.use(express.json());

// ==========================
// 3. Public endpoints
// ==========================
app.get('/health', (req, res) => {
  res.json({ status: 'ok' }); // drop timestamp in production
});

// --------------------------
// 4. Auth guard: pull from JWT secret
// --------------------------
const authenticate = (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer '))
    return res.status(401).json({ error: 'Missing or malformed token' });

  const token = authHeader.split(' ')[1];
  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET || 'dev-secret');
    req.user = payload;
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token' });
  }
};

// --------------------------
// 5. Protected /users endpoint
// --------------------------
app.get('/users', authenticate, (req, res) => {
  // TODO: Fetch from DB & filter on req.user.role
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ==========================
// 6. Server startup
// ==========================
const PORT = Number(process.env.PORT) || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

