```js
// app.js
require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const pino = require('pino');

const app = express();
const logger = pino({ level: process.env.LOG_LEVEL || 'info' });

const AUTH_SECRET = process.env.AUTH_SECRET;
if (!AUTH_SECRET) {
  throw new Error('Missing AUTH_SECRET env var');
}

/* --- generic middlewares --- */
app.use(express.json());        // parse JSON bodies
app.use(helmet());              // secure HTTP headers
app.use(
  rateLimit({
    windowMs: 1 * 60 * 1000,    // 1 minute
    max: 200,
  })
);

/* --- auth helper --- */
function requireAuth(req, res, next) {
  const bearer = req.headers.authorization;
  if (!bearer) return res.status(401).json({ msg: 'Missing token' });
  const token = bearer.split(' ')[1];
  jwt.verify(token, AUTH_SECRET, (err, payload) => {
    if (err) return res.status(403).json({ msg: 'Invalid token' });
    req.user = payload;
    next();
  });
}

/* --- routes --- */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', requireAuth, (req, res) => {
  // In a real app, only return what the user is authorized to see.
  // Here we fake an API call – always return an error if the user is unknown.
  if (!req.user) return res.status(404).json({ msg: 'User not found' });

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

/* --- error handling --- */
app.use((err, req, res, next) => {
  logger.error(err);
  res.status(500).json({ error: 'Internal Server Error' });
});

/* --- start server --- */
const port = process.env.PORT || 3000;
app.listen(port, () => logger.info(`Server listening on ${port}`));

module.exports = app;
```

