  try {
    const sql = `
      SELECT id, name, email
      FROM users
      WHERE name ILIKE $1 OR email ILIKE $1
    `;
    const { rows } = await client.query(sql, [`%${value.nameOrEmail}%`]);
    res.json(rows);
  } finally {
    client.release();
  }
});
```

