```js
// auth.js
const jwt = require('jsonwebtoken');
const express = require('express');
const router = express.Router();

const JWT_SECRET = process.env.JWT_SECRET || 'dev-secret'; // never keep this in code

// Middleware to protect routes
function ensureAuthenticated(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing token' });
  }
  const token = authHeader.slice(7);
  try {
    const payload = jwt.verify(token, JWT_SECRET);
    req.user = payload; // attach user info for downstream use
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

// Example “login” endpoint – in production use an actual user DB
router.post('/login', (req, res) => {
  const { username } = req.body;
  if (!username) return res.status(400).json({ error: 'Missing username' });

  // For demo purposes: accept any username
  const token = jwt.sign({ sub: username, iat: Date.now() }, JWT_SECRET, {
    expiresIn: '1h',
  });
  res.json({ token });
});

module.exports = { router, ensureAuthenticated };
```

